{
  "title": "CSCI-243: The Mechanics of Programming – Foundations Companion",
  "learningObjectives": [
    "Identify the core components of program structure (variables, expressions, control structures, functions) and explain their roles in algorithm design.",
    "Trace the program translation process from source code through lexical analysis, parsing, and execution, citing Python-specific mechanisms.",
    "Apply debugging and correctness techniques (tests, tracing, boundary analysis) to evaluate program behavior against intended specifications."
  ],
  "beats": [
    {
      "title": "Defining the Scope of CSCI-243",
      "claim": "CSCI-243 introduces students to program structure, execution mechanics, OS features, security, performance, and the translation process, with prerequisites including CSCI-140 or C-",
      "example": "A student enrolling in CSCI-243 must have earned a C- or better in CSCI-140, CSCI-142, CSCI-242, or an equivalent course such as SWEN-124.",
      "visualDirection": "Display the official catalog description text in a centered box with a subtle border; highlight the prerequisite list in a contrasting color.",
      "sourceIds": ["rit-csci-243"]
    },
    {
      "title": "The Foundation of Precise Problem Statements",
      "claim": "Programming begins with precise problem statements, input/output examples, and algorithms written independently of syntax.",
      "example": "Before coding, a student writes a problem statement: 'Given a list of integers, return the sum of all positive values,' and provides sample inputs/outputs.",
      "visualDirection": "Show a split-screen: left side contains the written problem statement and examples; right side shows a blank editor window ready for algorithm pseudocode.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Core Building Blocks: Variables, Expressions, and Control",
      "claim": "Variables represent values and state; expressions compute values; control structures select or repeat operations.",
      "example": "In Python, `x = 5` binds a variable, `x + 3` is an expression evaluating to 8, and `if x > 0:` is a control structure that repeats or branches based on the condition.",
      "visualDirection": "Render three distinct code snippets side-by-side, each labeled 'Variable', 'Expression', and 'Control Structure', with syntax highlighting.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Functions as Decomposed Operations",
      "claim": "Functions decompose a solution into named operations with parameters and results, enabling modular design.",
      "example": "A function `def sum_positive(nums):` takes a list parameter and returns a single integer result, isolating the summation logic.",
      "visualDirection": "Illustrate a flowchart where a large problem box splits into smaller boxes, each labeled with a function name and its parameters.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Recursion and Base Cases",
      "claim": "Recursion solves a problem through smaller instances and requires a base case to terminate.",
      "example": "The factorial function `def fact(n): if n == 0: return 1; return n * fact(n-1)` uses the base case `n == 0` to stop infinite recursion.",
      "visualDirection": "Show a tree diagram where each node represents a recursive call, with the root labeled `fact(5)` and leaves labeled `1` (the base case).",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Data Structures: Lists, Stacks, Queues, Trees, Graphs",
      "claim": "Lists represent ordered sequences; stacks use last-in first-out access; queues use first-in first-out access; trees represent hierarchy; graphs represent connected entities.",
      "example": "A stack of plates is popped from the top (LIFO), while a line of customers at a ticket booth is served from the front (FIFO).",
      "visualDirection": "Present five small diagrams: a horizontal list, a vertical stack with arrows pointing down, a queue with arrows pointing right, a binary tree, and a simple graph with nodes and edges.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Searching, Sorting, and Invariants",
      "claim": "Searching and sorting algorithms depend on representation and invariants that must hold throughout execution.",
      "example": "Binary search maintains the invariant that the target, if present, lies within the current search interval; quicksort maintains partition invariants to guarantee sorted output.",
      "visualDirection": "Animate a step-by-step binary search on a sorted array, highlighting the shrinking interval and the invariant condition at each step.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "The Python Translation Pipeline",
      "claim": "Python undergoes lexical analysis, parsing, and execution; the language reference specifies these stages and the data model behavior.",
      "example": "The string `'def hello(): pass'` is tokenized into identifiers, keywords, and delimiters during lexical analysis, then parsed into an abstract syntax tree before the interpreter executes it.",
      "visualDirection": "Show a linear pipeline graphic: Source Code → Lexical Analyzer → Parser → AST → Bytecode → Interpreter → Output, with brief labels under each stage.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Namespaces, Scopes, and Object Identity",
      "claim": "Python objects have identity, type, and value; names are bound to objects within namespaces and scopes, and the import system binds modules accordingly.",
      "example": "When `import math` runs, the module object is created, and the name `math` is bound in the current namespace, allowing access to `math.sqrt(4)`.",
      "visualDirection": "Display a Venn diagram with overlapping circles labeled 'Global Scope', 'Local Scope', and 'Module Namespace', with a small icon representing an imported module inside the module circle.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Debugging and Correctness: Tests, Tracing, and Boundaries",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "A test suite includes a case where the input list is empty (boundary) and another where the list contains negative numbers (error handling), and tracing reveals the function returns 0 for the empty case.",
      "visualDirection": "Show a split view: left side lists test cases (including boundary and error inputs), right side displays a trace log with line numbers and variable states for each case.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    }
  ]
}
